#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# shellcheck disable=SC2129
# encrypt-properties.sh — Encrypt key=value properties with the target environment's secure key into encrypted-output.json.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/utilities/encrypt-secure-property.yml
#   step   : "Encrypt Properties" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
# The shellcheck codes disabled above come from constructs inherited verbatim from that source.
#
# Inputs (environment):
#   MDF_ALGORITHM        <- ${{ parameters.algorithm }}  [default: AES]
#   MDF_ENVIRONMENT      <- ${{ parameters.environment }}  [required]
#   MDF_MODE             <- ${{ parameters.mode }}  [default: CBC]
#   MDF_PROPERTY_VALUES  <- ${{ parameters.propertyValues }}  [required]
#   MDF_TOOL_JAR_PATH    <- $(downloadTool.TOOL_JAR_PATH)  [default: (empty)]
# Environment read directly (Azure step env:):
#   LOCAL_SECURE_KEY  <- $(LOCAL_SECURE_KEY)
#   DEV_SECURE_KEY  <- $(DEV_SECURE_KEY)
#   SIT_SECURE_KEY  <- $(SIT_SECURE_KEY)
#   UAT_SECURE_KEY  <- $(UAT_SECURE_KEY)
#   PROD_SECURE_KEY  <- $(PROD_SECURE_KEY)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_ALGORITHM=AES}"
: "${MDF_ENVIRONMENT?MDF_ENVIRONMENT is required (Azure parameter environment)}"
: "${MDF_MODE=CBC}"
: "${MDF_PROPERTY_VALUES?MDF_PROPERTY_VALUES is required (Azure parameter propertyValues)}"
: "${MDF_TOOL_JAR_PATH=}"

# >>> extracted body
set -euo pipefail

ENV="${MDF_ENVIRONMENT}"
ALGO="${MDF_ALGORITHM}"
MODE="${MDF_MODE}"
TOOL_JAR="${MDF_TOOL_JAR_PATH}"

case "$ENV" in
  LOCAL) KEY="$LOCAL_SECURE_KEY" ;;
  DEV)   KEY="$DEV_SECURE_KEY" ;;
  SIT)   KEY="$SIT_SECURE_KEY" ;;
  UAT)   KEY="$UAT_SECURE_KEY" ;;
  PROD)  KEY="$PROD_SECURE_KEY" ;;
  *)     ci_log_error "Unknown environment: $ENV"; exit 1 ;;
esac

if [[ -z "$KEY" ]]; then
  ci_log_error "Encryption key not set for environment: $ENV"
  exit 1
fi

# Auto-detect JAR invocation: try java -jar first, fall back to java -cp
echo "Detecting secure-properties-tool invocation method..."
if java -jar "$TOOL_JAR" string encrypt "$ALGO" "$MODE" "detectkey1234" "detectval" &>/dev/null; then
  TOOL_CMD="java -jar $TOOL_JAR"
  echo "Using: java -jar (manifest Main-Class found)"
elif java -cp "$TOOL_JAR" com.mulesoft.tools.SecurePropertiesTool string encrypt "$ALGO" "$MODE" "detectkey1234" "detectval" &>/dev/null; then
  TOOL_CMD="java -cp $TOOL_JAR com.mulesoft.tools.SecurePropertiesTool"
  echo "Using: java -cp com.mulesoft.tools.SecurePropertiesTool"
else
  ci_log_error "secure-properties-tool.jar failed with both -jar and -cp invocation."
  echo "java -jar output:"
  java -jar "$TOOL_JAR" string encrypt "$ALGO" "$MODE" "detectkey1234" "detectval" 2>&1 || true
  echo "java -cp output:"
  java -cp "$TOOL_JAR" com.mulesoft.tools.SecurePropertiesTool string encrypt "$ALGO" "$MODE" "detectkey1234" "detectval" 2>&1 || true
  exit 1
fi

OUTPUT_DIR="$(ci_artifact_staging_dir)/encrypted-output"
mkdir -p "$OUTPUT_DIR"
OUTPUT_FILE="$OUTPUT_DIR/encrypted-output.json"

# Start JSON output
cat > "$OUTPUT_FILE" <<HEADER
{
  "environment": "$ENV",
  "algorithm": "$ALGO",
  "mode": "$MODE",
  "properties": {
HEADER
sed -i 's/^        //' "$OUTPUT_FILE"

FIRST=true
ERRORS=0

while IFS= read -r line; do
  [[ -z "$line" || "$line" == \#* ]] && continue

  # Validate input format
  if [[ "$line" != *"="* ]]; then
    ci_log_warning "Skipping invalid input (expected key=value format): $line"
    ERRORS=$((ERRORS + 1))
    continue
  fi

  # Split on first '=' only
  prop_key="${line%%=*}"
  prop_value="${line#*=}"

  # Trim whitespace
  prop_key="$(echo "$prop_key" | xargs)"
  prop_value="$(echo "$prop_value" | xargs)"

  if [[ -z "$prop_key" || -z "$prop_value" ]]; then
    ci_log_warning "Skipping entry with empty key or value: $line"
    ERRORS=$((ERRORS + 1))
    continue
  fi

  ENCRYPTED=$($TOOL_CMD string encrypt "$ALGO" "$MODE" "$KEY" "$prop_value" 2>&1) || {
    ci_log_warning "Failed to encrypt property: $prop_key"
    ci_log_warning "Tool output: $ENCRYPTED"
    ERRORS=$((ERRORS + 1))
    continue
  }

  if [ "$FIRST" = true ]; then
    FIRST=false
  else
    echo "," >> "$OUTPUT_FILE"
  fi
  printf '    "%s": "![%s]"' "$prop_key" "$ENCRYPTED" >> "$OUTPUT_FILE"
done <<< "${MDF_PROPERTY_VALUES}"

# Close JSON
echo "" >> "$OUTPUT_FILE"
echo "  }" >> "$OUTPUT_FILE"
echo "}" >> "$OUTPUT_FILE"

if [[ $ERRORS -gt 0 ]]; then
  ci_log_warning "$ERRORS property(ies) failed. Ensure input is in key=value format, one per line."
  ci_log_warning "Example: db.password=MySecret123"
fi

echo "Encryption complete. Output artifact ready."
